 Run the peer 35B-A3B route independently:

 ```bash
diff --git a/tests/targets/qwen3_6_27b/test_engine_qwen3_8_real.cpp b/tests/targets/qwen3_6_27b/test_engine_qwen3_8_real.cpp
new file mode 100644
index 00000000..494d9d15
--- /dev/null
+++ b/tests/targets/qwen3_6_27b/test_engine_qwen3_8_real.cpp
@@ -0,0 +1,92 @@
+#include "ginfer/engine.h"
+
+#include <algorithm>
+#include <cstddef>
+#include <cstdlib>
+#include <iostream>
+#include <utility>
+#include <vector>
+
+namespace {
+
+ginfer::EngineOptions engine_options(const char* artifact, bool mtp) {
+    ginfer::EngineOptions options;
+    options.artifact_path   = artifact;
+    options.max_context     = 512;
+    options.kv_capacity     = ginfer::KvCapacityPolicy::explicit_capacity(mtp ? 4096 : 512);
+    options.prefill_chunk   = 128;
+    options.kv_cache        = ginfer::KvCacheStorage::Int8Group64;
+    options.use_cuda_graph  = true;
+    options.max_concurrency = mtp ? 8 : 1;
+    if (mtp) {
+        options.speculative.backend       = ginfer::SpeculativeBackend::Mtp;
+        options.speculative.draft_tokens  = 3;
+        options.speculative.proposal_head = ginfer::ProposalHead::Optimized;
+    }
+    return options;
+}
+
+ginfer::RequestOptions greedy_options() {
+    ginfer::RequestOptions options;
+    options.execution.requested_output_tokens = 32;
+    options.execution.sampling.temperature    = 0.0F;
+    options.execution.allow_prefix_reuse      = false;
+    options.stop.include_model_defaults       = false;
+    return options;
+}
+
+} // namespace
+
+int main() {
+    const char* artifact = std::getenv("GINFER_QWEN3_8_27B_WEIGHTS");
+    if (artifact == nullptr || *artifact == '\0') {
+        std::cout << "skip: GINFER_QWEN3_8_27B_WEIGHTS is not set\n";
+        return 77;
+    }
+
+    const std::vector<ginfer::TokenId> prompt{
+        248045, 846,    198, 109266, 3709,  96220, 117443, 97913,
+        1710,   248046, 198, 248045, 74455, 198,   248068, 198,
+    };
+    std::vector<ginfer::TokenId> target_output;
+    {
+        ginfer::Engine target(engine_options(artifact, false));
+        if (target.load_summary().target != "qwen3_8_27b" ||
+            target.load_summary().weights_id != "groupwise-int") {
+            std::cerr << "Qwen3.8-27B real test loaded the wrong registered product\n";
+            return 1;
+        }
+        target_output =
+            target.generate(target.prepare_tokens(prompt), greedy_options()).generated_token_ids;
+        if (target_output.size() != 32) {
+            std::cerr << "ordinary target baseline did not generate 32 tokens\n";
+            return 1;
+        }
+    }
+
+    ginfer::Engine mtp(engine_options(artifact, true));
+    std::vector<ginfer::GenerationHandle> handles;
+    handles.reserve(8);
+    for (int request = 0; request < 8; ++request) {
+        handles.push_back(mtp.submit(mtp.prepare_tokens(prompt), greedy_options()));
+    }
+    for (std::size_t request = 0; request < handles.size(); ++request) {
+        const ginfer::GenerationResult result = handles[request].wait();
+        if (result.generated_token_ids != target_output ||
+            result.speculative.backend != ginfer::SpeculativeBackend::Mtp ||
+            result.speculative.rounds == 0) {
+            const auto mismatch =
+                std::mismatch(result.generated_token_ids.begin(), result.generated_token_ids.end(),
+                              target_output.begin(), target_output.end());
+            std::cerr << "concurrent MTP3 output diverged from the ordinary target at request "
+                      << request << ", token "
+                      << static_cast<std::size_t>(mismatch.first -
+                                                  result.generated_token_ids.begin())
+                      << '\n';
+            return 1;
+        }
+    }
+
+    std::cout << "ok\n";
+    return 0;
+}
